pub fn is_lambda_expr(e: Rc<Node>) -> bool {
    match (*e.expr_data.clone()).clone() {
    ExprData::ExprLambda { .. } => true,
    _ => false,
}
}

pub fn seed_override_map() -> Rc<HashMap<String, Rc<Node>>> {
    Rc::new(vec!["".to_string()]).iter().cloned().fold(v2_rt::rc_empty_map::<Rc<Node>>(), |acc: Rc<HashMap<String, Rc<Node>>>, k: String| v2_rt::rc_map_insert(acc.clone(), k.clone(), unit_type()))
}

pub fn fold_override_map(key: String, value: Rc<Node>) -> Rc<HashMap<String, Rc<Node>>> {
    v2_rt::rc_map_insert(seed_override_map(), key, value)
}

pub fn empty_override_map() -> Rc<HashMap<String, Rc<Node>>> {
    seed_override_map()
}

pub fn infer_arg_with_element_type(arg: &Rc<Node>, element_type: Rc<Node>, scope: &Rc<InferScope>) -> Rc<ArgInferResult> {
    {
        let ar = infer_expr(&arg_value(&arg), &scope, &Some(element_type));
Rc::new(ArgInferResult {
    typed_arg: make_arg_node(arg_name_at(arg.clone(), scope.type_env.clone().source_index.clone()), ar.typed.clone(), arg.span.clone(), arg.span.clone()),
    diagnostics: ar.diagnostics.clone(),
})
}
}

