pub fn resolved_type_name(n: &Rc<Node>) -> String {
    match n.inferred.clone().as_deref().cloned() {
    Some(InferredNode::Resolved { node: rt, .. }) => rt.name.clone(),
    _ => match n.children.clone().first().cloned() {
    Some(c) => c.name.clone(),
    None => "".to_string(),
},
}
}

